function detect(input,sampleRate){const n=Math.floor(input.length/2),data=new Float32Array(n);let power=0;for(let i=0;i<n;i++){const v=(input[2*i]+input[2*i+1])*.5;data[i]=v;power+=v*v;}const rms=Math.sqrt(power/n),rate=sampleRate/2;if(rms<.006)return null;const size=Math.floor(n/2),max=Math.min(Math.floor(rate/35),size-1),min=Math.max(2,Math.floor(rate/1800)),d=new Float32Array(max+1);for(let tau=1;tau<=max;tau++){let v=0;for(let i=0;i<size;i++){const x=data[i]-data[i+tau];v+=x*x;}d[tau]=v;}let sum=0;d[0]=1;for(let t=1;t<=max;t++){sum+=d[t];d[t]=sum?d[t]*t/sum:1;}let tau=-1;for(let t=min;t<max;t++)if(d[t]<.14){while(t+1<max&&d[t+1]<d[t])t++;tau=t;break;}if(tau<0)return null;const confidence=1-d[tau];if(confidence<.8)return null;const left=d[tau-1],mid=d[tau],right=d[tau+1],den=2*(2*mid-right-left),adjust=den?(right-left)/den:0,freq=rate/(tau+adjust);if(!Number.isFinite(freq)||freq<35||freq>1800)return null;return {frequency:freq,confidence,rms};}
