 if(clipped)return {state:'uncertain',midi,cents,automatic,message:'صدا خیلی بلند است؛ گوشی را کمی دورتر بگذار'};
 if(!stable)return {state:'waiting',midi,cents,automatic,message:'در حال تشخیص؛ سیم را تنها و یکنواخت بنواز'};
 if(Math.abs(cents)>180)return {state:'uncertain',midi,cents,automatic,message:'نت با هدف فاصله زیادی دارد؛ انتخاب سیم و اکتاو را بررسی کن'};
